insert into public.irritants (id,position,titre,court,signal,color,note,traitement,reponse,demo,proposition,pourquoi) values
('arrivee',0,'Arrivées mal préparées : annonces incomplètes, demandes au support trop tardives','Arrivées mal préparées','Arrivée mal préparée','#e11d48',11,'Assister','agent',true,'Agent d''intégration : à chaque annonce d''arrivée, il compare l''annonce à la checklist, liste ce qui manque, calcule le rétro-planning (poste 10 jours ouvrés, habilitation 15, badge 3) et prépare les messages au manager, à l''informatique et aux services généraux.','Lire une annonce écrite librement, repérer ce qui manque selon le profil (une habilitation pour un consultant cybersécurité) et rédiger trois messages adaptés demande compréhension et rédaction. Un formulaire aide, mais les managers continueront d''écrire par mail (mails 1, 4, 14, 21). L''agent prépare, la RH envoie.'),
('doc',1,'Documentation dispersée : plusieurs versions, liens inaccessibles, règles contradictoires','Documentation dispersée','Version incertaine','#7c3aed',10,'Simplifier (sans agent)','document',false,'Pas d''agent. Une page de référence unique, une seule version par document, lisible avant l''arrivée. La RH archive les anciennes versions.','Le problème n''est pas de trouver le document : il en existe trois. Un agent de recherche documentaire masquerait le désordre au lieu de le supprimer.'),
('questions',2,'Mêmes questions à chaque arrivée (télétravail, mutuelle, premier jour)','Questions récurrentes','Question récurrente','#0ea5e9',7,'Simplifier','document',false,'Une FAQ d''accueil jointe au mail de bienvenue. L''assistant en propose le contenu à partir des questions reçues, la RH valide.','Les questions sont prévisibles et les réponses stables : un document suffit. L''IA sert une seule fois, pour rédiger la FAQ.'),
('actions',3,'Actions de réunion jamais fermées, comptes rendus diffusés tard et peu lus','Actions jamais fermées','Action reportée','#10b981',7,'Simplifier','document',false,'Un modèle de compte rendu avec un tableau d''actions (responsable, échéance, statut) repris en tête du compte rendu suivant. En option, l''assistant prépare le brouillon à partir de notes tapées, jamais d''un enregistrement.','Ce qui manque, c''est un suivi des actions, pas une rédaction plus rapide. Visios et enregistrements sont exclus par Scalian.'),
('boucle',4,'Services généraux hors de la boucle des arrivées','Acteur oublié','Acteur oublié','#f59e0b',6,'Simplifier','reglage',false,'Ajouter les services généraux à la liste de diffusion des annonces d''arrivée.','Un réglage de messagerie suffit : aucune IA n''est nécessaire pour mettre quelqu''un en copie.'),
('pieces',5,'Pièces renvoyées faute d''accusé de réception','Pièces renvoyées','Renvoi','#64748b',6,'Automatiser','automatisation',false,'Une réponse automatique à la réception d''un dossier, avec la liste des pièces attendues. L''assistant ne lit jamais le contenu des pièces.','Accuser réception est une règle fixe. Les pièces contiennent des données personnelles : l''IA n''a rien à y faire.');
insert into public.irritant_status (irritant_id) select id from public.irritants;
insert into public.events (position,jour,src,ref,de_nom,titre,texte,irr,conf,aparte,live) values
(0,'J1','mail','Mail 1','Olivier Lambert, manager','Arrivée Hugo Lefèvre','Hugo arrive le lundi 15 comme consultant test logiciel. « Vous pouvez lancer le nécessaire ? »',ARRAY['arrivee']::text[],false,null,false),
(1,'J2','cr','CR-1',null,'Point hebdo intégration','« Arrivées à venir : aucune signalée. » Délai poste rappelé : 10 jours ouvrés. Mise à jour du livret d''accueil : reportée, prévue depuis septembre. Accès aux documents avant l''arrivée : sans responsable.',ARRAY['arrivee','doc','actions']::text[],false,null,false),
(2,'J2','mail','Mail 2','Camille Rousseau, RH','Bienvenue chez nous !','Liste des pièces à retourner, et lien vers le livret d''accueil : Livret_accueil_2024.pdf.',ARRAY['doc']::text[],false,null,false),
(3,'J3','mail','Mail 3','Hugo Lefèvre, futur employé','RE: Bienvenue chez nous !','« Le livret indique un jour de télétravail, en entretien on m''a parlé de deux. » Ne trouve pas le formulaire de mutuelle.',ARRAY['doc','questions']::text[],false,null,false),
(4,'J4','mail','Mail 4','Olivier Lambert, manager','Encore une arrivée le 15','Sarah arrive aussi le 15. « Il lui faudra un PC, je ne sais pas trop à qui faire la demande. »',ARRAY['arrivee']::text[],false,null,false),
(5,'J5','mail','Mail 5','Sarah Benmoussa, future employée','Lien mutuelle','Le lien vers le formulaire de mutuelle affiche « accès refusé ».',ARRAY['doc','questions']::text[],false,null,false),
(6,'J8','mail','Mail 6','Camille Rousseau, RH','2 postes pour lundi 15','Demande à l''informatique deux PC et les comptes, 5 jours ouvrés avant l''arrivée.',ARRAY['arrivee']::text[],false,null,false),
(7,'J9','cr','CR-2',null,'Point hebdo intégration','Postes commandés, livraison deux jours après l''arrivée. Formulaires de compte en attente. Livret : reporté. Checklist commune : « à lancer ». Services généraux excusés pour la 2e fois.',ARRAY['actions','boucle','arrivee']::text[],false,null,false),
(8,'J9','mail','Mail 7','Marc Dubois, informatique','RE: 2 postes pour lundi 15','« Le délai, c''est 10 jours ouvrés. » Livraison le 17 au plus tôt ; formulaire de création de compte manquant pour les deux.',ARRAY['arrivee']::text[],false,null,false),
(9,'J9','mail','Mail 8','Hugo Lefèvre, futur employé','Mes documents (2e envoi)','Renvoie ses documents : pas de confirmation du premier envoi.',ARRAY['pieces']::text[],false,null,false),
(10,'J10','mail','Mail 9','Camille Rousseau, RH','Formulaire création de compte','« Je crois que c''est la bonne version, il y en a deux sur le SharePoint. »',ARRAY['doc']::text[],false,null,false),
(11,'J11','mail','Mail 10','Sarah Benmoussa, future employée','Lundi : où et à quelle heure ?','Pas de programme reçu : agence ou client ? À quelle heure ?',ARRAY['questions']::text[],false,null,false),
(12,'J12','mail','Mail 11','Sandrine Petit, services généraux','Arrivées de lundi ?','« J''apprends à la machine à café que deux personnes arrivent lundi. » Badges non commandés.',ARRAY['boucle','arrivee']::text[],false,null,false),
(13,'J15','mail','Mail 12','Olivier Lambert, manager','Premier jour sans PC','Les deux arrivants passent la journée sans PC. « Est-ce qu''on peut éviter ça la prochaine fois ? »',ARRAY['arrivee']::text[],false,null,false),
(14,'J16','mail','Mail 13','Hugo Lefèvre, nouvel arrivant','Quel livret d''accueil ?','Trois livrets dans le dossier Accueil (2024, 2025_v2, 2025 FINAL) : « Lequel fait foi ? » Note de frais introuvable.',ARRAY['doc']::text[],false,null,false),
(15,'J16','mail','Mail 14','Julien Mercier, HRBP','Arrivée Antoine Roche lundi 22','Consultant sécurité, arrive dans 6 jours. « Tu as une checklist d''arrivée à jour ? Je n''ai que celle de 2023. »',ARRAY['arrivee','doc']::text[],false,null,false),
(16,'J17','mail','Mail 15','Antoine Roche, futur employé','Quelques questions avant lundi','Télétravail ? Mutuelle ? Heure d''arrivée lundi ? Les mêmes questions que les deux arrivants précédents.',ARRAY['questions']::text[],false,null,false),
(17,'J18','mail','Mail 16','Marc Dubois, informatique','Habilitation Antoine','Une habilitation cybersécurité se demande 15 jours ouvrés avant. « Personne ne me l''a demandée. »',ARRAY['arrivee']::text[],false,null,false),
(18,'J18','mail','Mail 17','Expéditeur masqué','Demande de rendez-vous confidentiel','Contenu non affiché.',ARRAY[]::text[],true,'Classé confidentiel sur son objet : contenu non analysé, non résumé, non inscrit au registre. Transmis tel quel au HRBP.',false),
(19,'J19','mail','Mail 18','Mutuelle','Votre lettre d''information de novembre','Newsletter.',ARRAY[]::text[],false,'Bruit : ignoré.',false),
(20,'J19','mail','Mail 19','Comité d''agence','Afterwork de fin d''année','Invitation.',ARRAY[]::text[],false,'Bruit : ignoré.',false),
(21,'J19','cr','CR-3',null,'Point hebdo intégration (réunion J16, diffusé J19)','Deux arrivants sans PC le premier jour. Chacun tient sa liste : tableur RH, outil informatique, cahier des services généraux. Livret : 3e report. Checklist commune : pas commencée.',ARRAY['actions','boucle','doc']::text[],false,null,false),
(22,'J19','cr','CR-4',null,'Comité RH mensuel','Premiers jours difficiles remontés par deux managers. Télétravail : l''accord 2025 dit deux jours, le livret un seul. Checklist commune déjà décidée au comité précédent. Les managers ne lisent pas les comptes rendus des points hebdo. Sujet reporté.',ARRAY['actions','doc','arrivee']::text[],false,null,false),
(23,'J22','mail','Mail 20','Karine Dumas, manager','Arrivée d''Antoine','PC de secours prêté, mais pas d''accès à l''outil des temps ni d''habilitation avant deux semaines : impossible de le positionner sur sa mission.',ARRAY['arrivee']::text[],false,null,false),
(1000,'Live','mail','Mail 21','Isabelle Moreau, manager','Arrivée Lucas Fabre lundi prochain','« Lucas Fabre nous rejoint lundi prochain comme consultant data. Merci de faire le nécessaire ! »',ARRAY['arrivee']::text[],false,null,true);
insert into public.arrivees (id,nom,poste) values ('lucas-fabre','Lucas Fabre','Consultant data');
insert into public.brouillons (id,arrivee_id,destinataire,objet,corps) values
('manager','lucas-fabre','Isabelle Moreau, manager','Arrivée de Lucas Fabre : 3 informations manquantes','Bonjour Isabelle, pour préparer l''arrivée de Lucas lundi, il nous manque le lieu du premier jour (agence ou client), le matériel nécessaire et les accès particuliers éventuels. Le délai habituel d''un poste (10 jours ouvrés) est dépassé : nous demandons un PC de secours. Vous pouvez aussi compléter l''annonce dans ACIA. Camille'),
('it','lucas-fabre','Marc Dubois, informatique','Arrivée lundi : PC de secours et comptes','Bonjour Marc, Lucas Fabre, consultant data, arrive lundi dans la BU Data. Le délai poste est dépassé : un PC de secours est-il possible ? Le formulaire de création de compte, signé par Isabelle Moreau, suit. Camille'),
('sg','lucas-fabre','Sandrine Petit, services généraux','Arrivée lundi : badge et place','Bonjour Sandrine, Lucas Fabre arrive lundi : badge et place à prévoir. Le lieu du premier jour est en cours de confirmation avec sa manager. Camille');
